// Map a NEXUS lead onto Bitrix24's crm.lead.add field shape AND build the
// identity material the two duplicate lookups downstream need.
//
// Two input shapes, both live:
//   * 'Called by Master Router' -> { lead: {...}, ai_decision: {...} }  (one lead)
//   * 'Fetch HOT Leads'         -> a flat leads row                     (backlog)
const j = $json;
const lead = j.lead || j;
const score = (j.ai_decision && j.ai_decision.score) ?? lead.ai_score ?? 0;

const clean = (v) => (v === undefined || v === null || v === false || v === '') ? null : String(v);
const name     = clean(lead.name) || 'Unknown lead';
const interest = clean(lead.vehicle_interest);
const rawEmail = clean(lead.email);
const phone    = clean(lead.phone);

// The Master Router synthesises '+<digits>@whatsapp.lead' for customers who
// arrive on WhatsApp with no email. That string is a ROUTING KEY, never a
// mailbox. It must not be used to look a lead up by EMAIL in Bitrix (it can
// never match anything a human typed) and it must not be written into a Bitrix
// EMAIL field, where a rep would read it as an address they can write to.
const SYNTHETIC = /@whatsapp\.lead$/i;
const realEmail = (rawEmail && !SYNTHETIC.test(rawEmail)) ? rawEmail : null;

// ---------------------------------------------------------------------------
// Phone variants. Bitrix's duplicate index normalises numbers, but not
// identically across portals and not at all for numbers stored with a local
// prefix. So we hand crm.duplicate.findbycomm every spelling of the SAME
// number that a human might have typed into the CRM, and let Bitrix match any
// of them. We never invent a country code we cannot justify: fabricating a
// +971 variant for an Indian mobile would be asking Bitrix about somebody
// else's number.
// ---------------------------------------------------------------------------
function phoneVariants(raw) {
  let d = String(raw || '').replace(/[^0-9]/g, '');
  if (d.slice(0, 2) === '00') d = d.slice(2);      // 00971... -> 971...
  if (!d || d.length < 7) return [];
  const out = [];
  const push = (v) => { if (v && out.indexOf(v) === -1) out.push(v); };
  // '+<digits>' only for something that can plausibly BE international. A
  // leading 0 is a national trunk prefix, and '+0...' is not a phone number.
  if (d[0] !== '0' && d.length >= 10) push('+' + d);
  push(d);
  // UAE subscriber part, if this is recognisably a UAE number. 971 + 9 digits
  // is a mobile, 971 + 8 is a landline; nationally those are 05xxxxxxxx and
  // 0Xxxxxxxx. A bare 5xxxxxxxx is the mobile subscriber part on its own.
  let sub = null;
  if (d.slice(0, 3) === '971' && (d.length === 12 || d.length === 11)) sub = d.slice(3);
  else if (d.length === 10 && d[0] === '0' && d[1] === '5') sub = d.slice(1);
  else if (d.length === 9 && d[0] === '0') sub = d.slice(1);
  else if (d.length === 9 && d[0] === '5') sub = d;
  if (sub) { push('+971' + sub); push('971' + sub); push('0' + sub); push(sub); }
  return out;
}
const phoneValues = phoneVariants(phone);

// ---------------------------------------------------------------------------
// The NEXUS comment block. Delimited so that on an update we can replace OUR
// paragraph in place and copy everything a rep typed through untouched. The
// markers are plain text: Bitrix lead COMMENTS may be stored as BB-code or as
// HTML depending on portal settings, and a plain bracketed token survives both
// without being eaten by a sanitiser.
// ---------------------------------------------------------------------------
const BEGIN = '[NEXUS-SYNC:BEGIN]';
const END   = '[NEXUS-SYNC:END]';
const blockBody = [
  interest ? 'Vehicle interest: ' + interest : null,
  'AI score: ' + score,
  lead.source ? 'Source: ' + lead.source : null,
  realEmail ? 'Email: ' + realEmail : null,
  phone ? 'Phone: ' + phone : null,
  'Synced automatically from NEXUS OS - edit above or below this block, not inside it'
].filter(Boolean).join('\n');
const nexusBlock = BEGIN + '\n' + blockBody + '\n' + END;

const opportunity = Number(lead.budget_aed) || 0;

// CREATE payload only. The update payload is built separately, from what
// Bitrix currently holds, in 'Build Update Payload'.
const fields = {
  TITLE: interest ? name + ' - ' + interest : name + ' - NEXUS OS lead',
  NAME: name,
  OPPORTUNITY: opportunity,
  CURRENCY_ID: 'AED',
  SOURCE_DESCRIPTION: clean(lead.source) || 'NEXUS OS',
  COMMENTS: nexusBlock
};
if (realEmail) fields.EMAIL = [{ VALUE: realEmail, VALUE_TYPE: 'WORK' }];
if (phone)     fields.PHONE = [{ VALUE: phone,     VALUE_TYPE: 'WORK' }];

return { json: {
  fields: fields,
  params: { REGISTER_SONET_EVENT: 'Y' },
  _lead_email:      rawEmail,          // real OR synthetic - the leads.email key
  _lead_real_email: realEmail,         // real only - safe to ask Bitrix about
  _lead_name:       name,
  _lead_id:         clean(lead.id),
  _bitrix_lead_id:  clean(lead.bitrix_lead_id),
  _crm_synced_at:   clean(lead.crm_synced_at),
  _phone_values:    phoneValues,
  _nexus_block:     nexusBlock,
  _nexus_begin:     BEGIN,
  _nexus_end:       END,
  _opportunity:     opportunity
} };

// Resolve WHICH Bitrix lead this NEXUS lead is, and whether writing is safe.
//
// THE BUG THIS REPLACES, WRITTEN DOWN SO NOBODY REINSTATES IT:
//   the old lookup filtered crm.lead.list on EMAIL, falling back to the literal
//   '__none__'. In Dubai a large share of the book arrives on WhatsApp with no
//   email at all, so every one of those leads missed the lookup, took the
//   create branch, and minted a brand-new Bitrix lead on EVERY run. The lookup
//   also swallowed its own errors, so a 403 or a timeout produced the same
//   "not found" as a genuine miss -- and therefore the same duplicate.
//
// IDENTITY ORDER (most authoritative first):
//   1. leads.bitrix_lead_id  - a crosswalk we wrote ourselves after a confirmed
//                              write. Survives the customer changing number.
//   2. PHONE via crm.duplicate.findbycomm - the UAE key. Every spelling of the
//                              number is offered; Bitrix's own duplicate index
//                              does the normalising, so a lead stored as
//                              050 123 4567 still matches +971501234567.
//   3. EMAIL via crm.duplicate.findbycomm - real addresses only.
// A lookup that FAILED is never read as "not found".
const m = $('Map Lead to Bitrix24 Lead').item.json;

function probe(nodeName) {
  let it;
  try { it = $(nodeName).item; }
  catch (e) { return { failed: true, ids: [] }; }
  const j = (it && it.json) || {};
  // onError:'continueRegularOutput' delivers transport failures as data.
  if (j.error !== undefined) return { failed: true, ids: [] };
  // A Bitrix REST error can also arrive with HTTP 200 and no `result` key.
  if (j.result === undefined) return { failed: true, ids: [] };
  const r = j.result;
  let ids = (r && r.LEAD) ? r.LEAD : [];
  if (!Array.isArray(ids)) ids = [ids];
  ids = ids.map(Number).filter(n => Number.isFinite(n) && n > 0);
  return { failed: false, ids: ids };
}

const byPhone = probe('Find Existing Lead');
const byEmail = probe('Find Lead by Email');
const lookup_failed = byPhone.failed || byEmail.failed;

const stored = Number(m._bitrix_lead_id);
const storedOk = Number.isFinite(stored) && stored > 0;

let existing_id = null, id_source = null;
if (storedOk)                { existing_id = stored;                 id_source = 'stored crosswalk leads.bitrix_lead_id'; }
else if (byPhone.ids.length) { existing_id = Math.min.apply(null, byPhone.ids); id_source = 'Bitrix phone duplicate index'; }
else if (byEmail.ids.length) { existing_id = Math.min.apply(null, byEmail.ids); id_source = 'Bitrix email duplicate index'; }

// Everything the duplicate index matched, deduplicated. More than one id means
// duplicates ALREADY exist in Bitrix for this human. We keep the LOWEST id --
// the oldest record, the one reps have been typing into -- and we name the rest
// in the audit row so they can be merged. This workflow never deletes in Bitrix.
const all = [];
for (const n of byPhone.ids.concat(byEmail.ids)) if (all.indexOf(n) === -1) all.push(n);
all.sort((a, b) => a - b);

const hasIdentity = !!(m._phone_values && m._phone_values.length) || !!m._lead_real_email;

let write_mode = 'create', _no_write_reason = null, _no_write_fatal = false;
if (existing_id) {
  write_mode = 'update';
} else if (lookup_failed) {
  // Creating here is precisely how the duplicates got made. Not writing is
  // recoverable -- crm_synced_at is not stamped, so the next run retries.
  write_mode = 'create_blocked';
  _no_write_reason = 'Bitrix duplicate lookup did not answer ('
    + [byPhone.failed ? 'phone probe failed' : null, byEmail.failed ? 'email probe failed' : null]
      .filter(Boolean).join(', ')
    + ') - creating now could duplicate an existing lead, so nothing was written';
  _no_write_fatal = true;
} else if (!hasIdentity) {
  // A lead with neither a usable phone nor a real email can never be matched
  // again. Creating it guarantees a duplicate on the next run for the same human.
  write_mode = 'create_blocked';
  _no_write_reason = 'lead has neither a usable phone number nor a real email address, '
    + 'so it can never be de-duplicated in Bitrix - refused rather than create an '
    + 'unmatchable record';
  _no_write_fatal = true;
}

return { json: {
  existing_id:     existing_id,
  id_source:       id_source,
  duplicate_ids:   all,
  lookup_failed:   lookup_failed,
  write_mode:      write_mode,
  _no_write_reason: _no_write_reason,
  _no_write_fatal:  _no_write_fatal,
  // Create payload, untouched. Contact arrays are set ONCE, at creation.
  fields:          m.fields,
  params:          m.params,
  _lead_email:      m._lead_email,
  _lead_real_email: m._lead_real_email,
  _lead_name:       m._lead_name,
  _lead_id:         m._lead_id,
  _crm_synced_at:   m._crm_synced_at,
  _opportunity:     m._opportunity
} };

// Normalise the Bitrix24 response into an audit row.
const r = $json || {};
let d = {};
try { d = $('Decide Update or Create').item.json || {}; } catch (e) { d = {}; }
// Only present on the update branch; $('...') THROWS on the create branch, so
// this needs try/catch rather than ?. or ||.
let u = {};
try { u = $('Build Update Payload').item.json || {}; } catch (e) { u = {}; }

const mode = d.write_mode || (d.existing_id ? 'update' : 'create');
const isUpdate = mode === 'update';

// Set by 'Build Update Payload' (nothing to change / read-before-write failed)
// or by 'Decide Update or Create' (unsafe to create). Its presence means NO
// Bitrix write was attempted for this item.
const noWrite = r._no_write_reason || u._no_write_reason || d._no_write_reason || null;
const noWriteFatal = !!(r._no_write_fatal || u._no_write_fatal || d._no_write_fatal);
const wroteFields = Array.isArray(u._changed) ? u._changed : [];

let status, summary, bitrixId = null, attempted = !noWrite;

if (noWrite) {
  status  = noWriteFatal ? 'FAILED' : 'SUCCESS';
  bitrixId = d.existing_id || null;
  summary = 'Bitrix24 lead ' + (isUpdate ? 'update' : 'creation') + ' not attempted: '
          + String(noWrite).substring(0, 260);
} else {
  const ok = isUpdate ? (r.result === true) : !!r.result;
  let reason = null;
  if (!ok) {
    const raw = r.error ? (r.error.message || JSON.stringify(r.error))
                        : (r.error_description || r.error || 'unknown error');
    const mm = String(raw).match(/\{.*\}/s);
    if (mm) { try { const p = JSON.parse(mm[0]); reason = p.error_description || p.error || String(raw); }
              catch (e) { reason = String(raw); } }
    else { reason = String(raw); }
    reason = reason.replace(/\\u0022/g, '"').substring(0, 300);
  }
  bitrixId = isUpdate ? (d.existing_id || null) : (ok ? Number(r.result) : null);
  status   = ok ? 'SUCCESS' : 'FAILED';
  summary  = ok
    ? ('Bitrix24 lead ' + (isUpdate ? 'updated' : 'created') + ' (ID ' + bitrixId + ')'
       + (d.id_source ? ' via ' + d.id_source : '')
       + (wroteFields.length ? ' [wrote ' + wroteFields.join(', ') + ']' : ''))
    : ('Bitrix24 lead ' + (isUpdate ? 'update' : 'creation') + ' failed: ' + reason);
}

// Duplicates that ALREADY exist in Bitrix. The identity fix stops new ones; it
// cannot undo old ones, so every run that sees more than one matching lead says
// so, in the one place a human reads. Grep audit_log for 'DUPLICATES IN BITRIX'.
const dupes = Array.isArray(d.duplicate_ids) ? d.duplicate_ids : [];
const dupeNote = dupes.length > 1
  ? ' | DUPLICATES IN BITRIX: lead ids ' + dupes.join(',')
    + ' all match this customer; kept ' + (bitrixId || dupes[0]) + ', merge the rest'
  : '';

return { json: {
  workflow:   'wf_108 ERP Sync - Bitrix24',
  status:     status,
  lead_name:  d._lead_name || null,
  lead_email: d._lead_email || null,
  summary:    summary + dupeNote,
  // Consumed by 'Delivery Report' and 'Link Back to Supabase'; both strip these
  // before anything is written to audit_log, which is autoMapInputData and
  // would reject an unknown column.
  _mode:            mode,
  _write_attempted: attempted,
  _stamp:           status === 'SUCCESS',
  _lead_email:      d._lead_email || null,
  bitrix_lead_id:   bitrixId
} };

// This node sits ONLY on the public webhook branch.
// 'Called by Master Router' connects straight to the next node and never
// reaches here, so the trusted sub-workflow path is untouched by this guard.
//
// 'Verify JWT' runs with onError = continueRegularOutput, so a rejected token
// arrives as data rather than as a failed HTTP node. Supabase GET
// /auth/v1/user returns the user object on success; no .id means rejected.
const auth = $input.first().json || {};
if (!auth.id) {
  throw new Error('ERP sync rejected: unauthorized. A valid Supabase session token is required in the Authorization header.');
}

// Re-emit the ORIGINAL request untouched so the downstream node sees exactly
// the shape it saw before this guard was inserted.
return $('ErpSyncWebhook').all();

// Verify every node whose success this audit row is about to claim.
// $('Node') THROWS for a node that did not run on the taken branch and neither
// ?. nor || can rescue it - only try/catch - so every lookup below is guarded
// and the claim list is built from the branch that ACTUALLY ran.
const base = $json || {};
let d = {};
try { d = $('Decide Update or Create').item.json || {}; } catch (e) { d = {}; }

const mode      = base._mode || d.write_mode || (d.existing_id ? 'update' : 'create');
const attempted = base._write_attempted !== false;

// Both probes are now CRITICAL. The old version marked the duplicate check
// non-critical, which is exactly why a swallowed lookup could silently mint a
// duplicate while the audit row still said SUCCESS.
const CLAIMED = [
  { node: 'Find Existing Lead', what: 'Bitrix24 duplicate lookup by phone', critical: true },
  { node: 'Find Lead by Email', what: 'Bitrix24 duplicate lookup by email', critical: true },
];
if (mode === 'update') {
  CLAIMED.push({ node: 'Fetch Existing Bitrix Lead', what: 'read-before-write of the existing Bitrix lead', critical: true });
  if (attempted) CLAIMED.push({ node: 'Update Bitrix24 Lead', what: 'Bitrix24 CRM lead update', critical: true });
} else if (mode === 'create' && attempted) {
  CLAIMED.push({ node: 'Create Bitrix24 Lead', what: 'Bitrix24 CRM lead creation', critical: true });
}

function check(c) {
  let it;
  try { it = $(c.node).item; }
  catch (e) { return Object.assign({}, c, { ok: false, why: 'node did not run on this branch' }); }
  if (!it) return Object.assign({}, c, { ok: false, why: 'node produced no items' });
  const j = it.json || {};
  if (j.error !== undefined) {
    const m = (j.error && (j.error.message || j.error.description)) || j.error;
    return Object.assign({}, c, { ok: false, why: String(m).slice(0, 300) });
  }
  // A Bitrix REST error can arrive with HTTP 200 and no `result` key at all.
  if (c.node.indexOf('Find ') === 0 && j.result === undefined) {
    return Object.assign({}, c, { ok: false, why: 'no result key in the Bitrix response' });
  }
  return Object.assign({}, c, { ok: true });
}

const results = CLAIMED.map(check);
const dropped = results.filter(r => !r.ok);
const fatal   = dropped.filter(r => r.critical);

// 'Build Audit Row' already judged the Bitrix payload itself; a 200 carrying
// result:false has no `error` key, so keep that verdict rather than raising it.
const priorFailed = String(base.status || '').toUpperCase() === 'FAILED';

const status = (fatal.length || priorFailed) ? 'FAILED'
             : dropped.length               ? 'PARTIAL'
             : 'SUCCESS';

const note = dropped.length
  ? dropped.length + ' of ' + results.length + ' claimed steps did not land'
  : 'all ' + results.length + ' claimed steps verified';

// 'Log to Supabase audit_log' inserts with autoMapInputData, so emit EXACTLY
// the columns audit_log has - an extra key is an unknown column and fails the
// insert. The delivery verdict lands in `status` and `summary`, nowhere else.
return { json: {
  workflow:   base.workflow,
  status:     status,
  lead_name:  base.lead_name,
  lead_email: base.lead_email,
  summary:    base.summary + ' | ' + note
              + (dropped.length ? ' [' + dropped.map(r => r.what + ' - ' + r.why).join('; ') + ']' : ''),
} };

// Decide what an AUTOMATED push is allowed to change in a record that humans
// also edit by hand. The old update sent TITLE, OPPORTUNITY and COMMENTS
// wholesale from the Supabase row, so a rep who typed notes into Bitrix lost
// them the next time this workflow ran. NEXUS is no longer the winner by
// default; it is the winner only for fields no human is expected to author.
//
// FIELD OWNERSHIP
//   COMMENTS ............ APPEND-ONLY. Everything outside the [NEXUS-SYNC]
//                         block is copied through byte for byte; our own block
//                         is replaced in place so the field cannot grow forever.
//   OPPORTUNITY ......... FILL-IF-EMPTY. A rep's negotiated figure outranks a
//                         budget parsed out of a WhatsApp message.
//   TITLE, NAME ......... NEVER on update. These are the record's human label;
//                         reps rename leads to their own conventions and fix
//                         transliterations that a WhatsApp profile got wrong.
//   PHONE, EMAIL ........ NEVER on update. Bitrix APPENDS to multi-value
//                         fields, so re-sending stacks duplicate entries.
//   SOURCE_DESCRIPTION .. NEVER on update. First-touch provenance is history.
//   STATUS_ID,
//   ASSIGNED_BY_ID ...... NEVER, at all. Pipeline stage and ownership are
//                         human decisions and this workflow has no opinion.
const g = $json || {};
const d = $('Decide Update or Create').item.json;
const m = $('Map Lead to Bitrix24 Lead').item.json;

// crm.lead.get returns { result: {...} }. onError:'continueRegularOutput' means
// a failure arrives as data, and a Bitrix REST error can arrive with HTTP 200.
const existing = (g && g.error === undefined && g.result && !Array.isArray(g.result)) ? g.result : null;
const readFailed = !existing;

const BEGIN = m._nexus_begin, END = m._nexus_end;
const fields = {};
const changed = [];
let _no_write_reason = null, _no_write_fatal = false;

if (readFailed) {
  // NEVER WRITE A FIELD YOU COULD NOT READ. Writing COMMENTS blind here would
  // be the original bug wearing a different hat.
  _no_write_reason = 'could not read the existing Bitrix lead (crm.lead.get returned '
    + (g && g.error !== undefined ? 'an error' : 'no usable result')
    + ') - refusing to overwrite fields we have not seen';
  _no_write_fatal = true;
} else {
  const prior = String(existing.COMMENTS == null ? '' : existing.COMMENTS);

  // Strip only OUR block. Whatever a rep typed above or below it is theirs and
  // is copied through byte for byte; the ONLY whitespace we touch is the seam
  // left behind where our own block used to sit.
  let human;
  const s = prior.indexOf(BEGIN);
  if (s !== -1) {
    const e = prior.indexOf(END, s);
    const head = prior.slice(0, s).replace(/\s+$/, '');
    const tail = (e === -1 ? '' : prior.slice(e + END.length)).replace(/^\s+/, '').replace(/\s+$/, '');
    human = (head && tail) ? (head + '\n\n' + tail) : (head || tail);
  } else {
    human = prior.replace(/\s+$/, '');
  }

  const merged = (human ? human + '\n\n' : '') + m._nexus_block;
  if (merged !== prior) { fields.COMMENTS = merged; changed.push('COMMENTS'); }

  // Has a human touched this record since OUR last confirmed push? If so we
  // stay out of the money field entirely, even to fill a blank.
  const bMod = Date.parse(existing.DATE_MODIFY || '');
  const nSync = Date.parse(m._crm_synced_at || '');
  const touchedSinceUs = isFinite(bMod) && isFinite(nSync) && bMod > nSync;

  const currentOpp = Number(existing.OPPORTUNITY || 0);
  if (!touchedSinceUs && m._opportunity > 0 && !(currentOpp > 0)) {
    fields.OPPORTUNITY = m._opportunity;
    fields.CURRENCY_ID = 'AED';
    changed.push('OPPORTUNITY');
  }

  if (!changed.length) {
    _no_write_reason = 'nothing to change - the NEXUS block is already current and '
      + 'no human-owned field is ours to write';
    _no_write_fatal = false;   // this is a healthy no-op, not a failure
  }
}

return { json: Object.assign({}, d, {
  fields: fields,
  // Silent on updates: an automated field refresh must not raise a notification
  // in every rep's Bitrix activity stream. Creates still register the event.
  params: { REGISTER_SONET_EVENT: 'N' },
  _changed: changed,
  _no_write_reason: _no_write_reason,
  _no_write_fatal: _no_write_fatal,
  _bitrix_date_modify: existing ? (existing.DATE_MODIFY || null) : null,
  _bitrix_comments_len: existing ? String(existing.COMMENTS == null ? '' : existing.COMMENTS).length : null
}) };
